R=/scratch/jjyeung/orch_n30; W=$R/sb_scalerev
free -g | sed -n 2p; mkdir -p $W/work/tmp; cat $R/sb_cursor_probe/AGENTS.md > $W/AGENTS.md
echo  | base64 -d > $W/PROMPT.md; echo  | base64 -d > $W/RECORD.md; sha256sum $W/PROMPT.md $W/RECORD.md | cut -c1-16
cd $W && tmux new-session -d -s sb_scalerev "TMPDIR=$W/work/tmp OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 20; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; ps -eo etime,args | grep -v grep | grep -c "claude-opus-5-5-xhigh"
